import type { StockAssetMeta } from '@parlante/shared';

/**
 * Catalogue of the built-in stock assets (backgrounds and music). Owner: content.
 *
 * Everything listed here is GENERATED BY CODE — no downloaded or third-party media — by
 * `pnpm --filter @parlante/stock-assets generate` (scripts/generate.ts) and committed under
 * `assets/backgrounds/` and `assets/music/`. `assets/manifest.json` records size and hash of
 * every file; the package tests fail when catalogue, manifest and files disagree.
 *
 * Isomorphic: this file only holds metadata, so templates and the web can import ids and
 * names. The bytes are read in Node through `@parlante/stock-assets/node`
 * (`getStockAssetData`, `stockAssetFilePath`), which is what `GET /api/stock-assets/:stockId/file`
 * serves and what the worker loads when rendering.
 *
 * Ids are STABLE: compositions store them in `MediaRef { source: 'stock', stockId }`. Never
 * rename or remove one; add new ones at the end of its list.
 *
 * Add an asset = add its painter (src/generators/backgrounds.ts) or its track
 * (src/generators/music/tracks.ts), its entry here, and run the generate script.
 */

