export type StockAssetId = StockBackgroundId | StockMusicId;

/**
 * Side of the square background masters. With `fit: 'cover'` one file fills 16:9, 9:16 and
 * 1:1 canvases at 1080p without upscaling; the designs keep their subject in the centre.
 */
export const STOCK_BACKGROUND_SIZE = 1920;

/** Loudness every music track is mastered to (integrated, LUFS). */
export const STOCK_MUSIC_LUFS = -16;

interface Texts {
  name: string;
  tags: string[];
  en: { name: string; tags: string[] };
}

interface BackgroundDef extends Texts {
  /**
   * Overall brightness: put light text on `dark` and `vivid` backgrounds, dark text on `light`.
   */
  tone: 'dark' | 'light' | 'vivid';
  group: 'gradient' | 'pattern' | 'set';
}

const text = (name: string, tags: string[], enName: string, enTags: string[]): Texts => ({
  name,
  tags,
  en: { name: enName, tags: enTags },
});

const TONE_TAG = {
  dark: ['oscuro', 'dark'],
  light: ['claro', 'light'],
  vivid: ['vivo', 'vivid'],
} as const;
const GROUP_TAG = {
  gradient: ['degradado', 'gradient'],
  pattern: ['patrón', 'pattern'],
  set: ['escenario', 'set'],
} as const;

const bg = (
  group: BackgroundDef['group'],
  tone: BackgroundDef['tone'],
  name: string,
  tags: string[],
  enName: string,
  enTags: string[],
): BackgroundDef => ({
  group,
  tone,
  ...text(name, [GROUP_TAG[group][0], ...tags, TONE_TAG[tone][0]], enName, [
    GROUP_TAG[group][1],
    ...enTags,
    TONE_TAG[tone][1],
  ]),
});

