/** Sample rate of every music track. */
export const STOCK_MUSIC_SAMPLE_RATE = 48_000;

interface MusicDef extends Texts {
  bpm: number;
  /** Length of the loop in 4/4 bars. */
  bars: number;
  /** Exact loop length in samples per channel (a whole number of bars). */
  samples: number;
  durationMs: number;
}

const music = (
  bpm: number,
  bars: number,
  name: string,
  tags: string[],
  enName: string,
  enTags: string[],
): MusicDef => {
  const samples = Math.round(((bars * 4 * 60) / bpm) * STOCK_MUSIC_SAMPLE_RATE);
  return {
    bpm,
    bars,
    samples,
    durationMs: Math.round((samples / STOCK_MUSIC_SAMPLE_RATE) * 1000),
    ...text(name, tags, enName, enTags),
  };
};

