export const STOCK_BACKGROUND_MIME = 'image/jpeg';
export const STOCK_MUSIC_MIME = 'audio/mp4';

export const STOCK_ASSETS: readonly StockAssetMeta[] = [
  ...STOCK_BACKGROUND_IDS.map((id): StockAssetMeta => {
    const def = BACKGROUNDS[id];
    return {
      id,
      kind: 'image',
      category: 'background',
      name: def.name,
      tags: def.tags,
      mimeType: STOCK_BACKGROUND_MIME,
      width: STOCK_BACKGROUND_SIZE,
      height: STOCK_BACKGROUND_SIZE,
      durationMs: null,
      en: def.en,
    };
  }),
  ...STOCK_MUSIC_IDS.map((id): StockAssetMeta => {
    const def = MUSIC[id];
    return {
      id,
      kind: 'audio',
      category: 'music',
      name: def.name,
      tags: def.tags,
      mimeType: STOCK_MUSIC_MIME,
      width: null,
      height: null,
      durationMs: def.durationMs,
      en: def.en,
    };
  }),
];

export function listStockAssets(): StockAssetMeta[] {
  return STOCK_ASSETS.map((asset) => structuredClone(asset));
}

export function isStockAssetId(stockId: string): stockId is StockAssetId {
  return STOCK_ASSETS.some((a) => a.id === stockId);
}

export function getStockAssetMeta(stockId: string): StockAssetMeta | null {
  const found = STOCK_ASSETS.find((a) => a.id === stockId);
  return found ? structuredClone(found) : null;
}

/** What the catalogue knows beyond the API metadata. */
export interface StockAssetDetails {
  id: StockAssetId;
  /** Path of the committed file, relative to `packages/stock-assets/assets/`. */
  file: string;
  /** Backgrounds: overall brightness (choose the text colour from it). */
  tone: 'dark' | 'light' | 'vivid' | null;
  /** Backgrounds: gradient, pattern or abstract set. */
  group: 'gradient' | 'pattern' | 'set' | null;
  /** Music: tempo. */
  bpm: number | null;
  /**
   * Music: the file is a seamless loop. Decoded once (48 kHz stereo) it yields exactly
   * `loopSamples` samples per channel and its last sample flows into the first one, so repeat
   * the DECODED audio (WebAudio `AudioBufferSourceNode.loop`, ffmpeg `aloop` filter). Do not
   * loop by re-opening the file (ffmpeg `-stream_loop`): restarting an AAC decoder fades the
   * first 20 ms in and the seam becomes audible.
   */
  loop: boolean;
  loopSamples: number | null;
}

export function getStockAssetDetails(stockId: string): StockAssetDetails | null {
  if (!isStockAssetId(stockId)) return null;
  if (stockId in BACKGROUNDS) {
    const def = BACKGROUNDS[stockId as StockBackgroundId];
    return {
      id: stockId,
      file: `backgrounds/${stockId}.jpg`,
      tone: def.tone,
      group: def.group,
      bpm: null,
      loop: false,
      loopSamples: null,
    };
  }
  const def = MUSIC[stockId as StockMusicId];
  return {
    id: stockId,
    file: `music/${stockId}.m4a`,
    tone: null,
    group: null,
    bpm: def.bpm,
    loop: true,
    loopSamples: def.samples,
  };
}
